import{bV as l,aL as e,u as i,G as t}from"./chunks/framework.BfzMay2U.js";const p=JSON.parse('{"title":"开发规则","description":"","frontmatter":{"title":"开发规则","date":"2026-10-14T23:31:10.000Z"},"headers":[],"relativePath":"ai/rules/standard.md","filePath":"ai/rules/standard.md"}'),o={name:"ai/rules/standard.md"};function r(s,a,n,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="开发规则" tabindex="-1">开发规则 <a class="header-anchor" href="#开发规则" aria-label="Permalink to &quot;开发规则&quot;">​</a></h1><h2 id="项目整体架构通用规范" tabindex="-1">项目整体架构通用规范 <a class="header-anchor" href="#项目整体架构通用规范" aria-label="Permalink to &quot;项目整体架构通用规范&quot;">​</a></h2><ol><li>项目必须按功能模块拆分，禁止编写超大单体文件</li><li>通用工具、公共方法统一抽离封装，全局复用</li><li>业务逻辑和页面、接口入口分离，不把所有的逻辑写在入口处</li><li>目录结构清晰，同类文件统一归类存放</li></ol><h2 id="vue3-开发规则" tabindex="-1">Vue3 开发规则 <a class="header-anchor" href="#vue3-开发规则" aria-label="Permalink to &quot;Vue3 开发规则&quot;">​</a></h2><ol><li>统一使用 Vue3 script setup 组合式 API</li><li>组件大驼峰命名，变量方法小驼峰命名</li><li>接口请求统一封装，不在页面内直接写请求代码</li><li>页面和通用组件拆分，可复用逻辑抽离组合式函数</li><li>严格按目录分层：页面、组件、接口、工具分开存放</li></ol><h2 id="python-fastapi-开发规则" tabindex="-1">Python FastAPI 开发规则 <a class="header-anchor" href="#python-fastapi-开发规则" aria-label="Permalink to &quot;Python FastAPI 开发规则&quot;">​</a></h2><ol><li>遵循 Python 基础命名规范，变量和文件使用下划线命名</li><li>FastAPI 按路由模块化拆分，不同业务分开路由文件</li><li>数据模型、路由接口、业务逻辑分层编写</li><li>统一接口返回格式，参数做好基础校验</li><li>业务逻辑抽离到单独方法，路由只做接收和响应</li></ol><h2 id="利用-ai-工具扫清开发障碍" tabindex="-1">利用 AI 工具扫清开发障碍 <a class="header-anchor" href="#利用-ai-工具扫清开发障碍" aria-label="Permalink to &quot;利用 AI 工具扫清开发障碍&quot;">​</a></h2><ul><li><p>学习新技术：让 AI 为你生成有针对性的练习和例子</p><p><code>我正在学习 Go 语言的基础，请出 5 个难度递进的练习题，并在我给出答案后判断对错、解释原理</code></p></li><li><p>完成功能后，讲代码提交给 AI 进行审查，学习最佳实践</p><p><code>这段实现排序的代码可以工作，但请从性能、可读性、可维护性三个角度提出改进建议，并解释为什么。</code></p></li></ul>',9)])])}const _=l(o,[["render",r]]);export{p as __pageData,_ as default};
